import operator
import re


_TOKEN = re.compile(r"[ \t]+|[0-9]+|//|\*\*|.", re.DOTALL)
_PRECEDENCE = {"+": 1, "-": 1, "*": 2, "//": 2, "%": 2,
               "u+": 3, "u-": 3, "**": 4}
_BINARY = {"+": operator.add, "-": operator.sub, "*": operator.mul,
           "//": operator.floordiv, "%": operator.mod, "**": operator.pow}


def _postfix(text):
    """Validate the whole expression before performing arithmetic."""
    output = []
    operators = []
    need_operand = True
    for token in _TOKEN.findall(text):
        if token[0] in " \t":
            continue
        if need_operand:
            if token in ("+", "-"):
                operators.append("u" + token)
            elif token == "(":
                operators.append(token)
            elif "0" <= token[0] <= "9":
                if len(token) > 1 and token.startswith("0"):
                    raise ValueError("leading zero")
                value = 0
                for digit in token:
                    value = value * 10 + int(digit)
                output.append(value)
                need_operand = False
            else:
                raise ValueError("expected operand")
        elif token == ")":
            while operators and operators[-1] != "(":
                output.append(operators.pop())
            if not operators:
                raise ValueError("unexpected closing parenthesis")
            operators.pop()
        elif token in _BINARY:
            while operators and operators[-1] != "(":
                top = _PRECEDENCE[operators[-1]]
                if top < _PRECEDENCE[token] or (top == _PRECEDENCE[token] and token == "**"):
                    break
                output.append(operators.pop())
            operators.append(token)
            need_operand = True
        else:
            raise ValueError("expected operator")
    if need_operand or "(" in operators:
        raise ValueError("incomplete expression")
    output.extend(reversed(operators))
    return output


def evaluate(text):
    """Return the integer value of an arithmetic expression."""
    if not isinstance(text, str):
        raise ValueError("expected text")
    values = []
    for token in _postfix(text):
        if isinstance(token, int):
            values.append(token)
        elif token == "u-":
            values[-1] = -values[-1]
        elif token != "u+":
            right = values.pop()
            if token == "**" and right < 0:
                raise ValueError("negative exponent")
            values[-1] = _BINARY[token](values[-1], right)
    return values[0]
